Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The tcf_csum_act() function in act_csum.c processes nested VLAN headers by directly accessing skb->data and pulling VLAN_HLEN without first verifying that the entire VLAN header is present in the linear area using pskb_may_pull(). This can cause out-of-bounds reads and skb invariants violation when only part of the inner VLAN header is linearized.

Here is the patch:

 TC_INDIRECT_SCOPE int tcf_csum_act(struct sk_buff *skb,
 				   const struct tc_action *a,
 				   struct tcf_result *res)
 {
 	struct tcf_csum *p = to_tcf_csum(a);
 	bool orig_vlan_tag_present = false;
 	unsigned int vlan_hdr_count = 0;
 	struct tcf_csum_params *params;
 	u32 update_flags;
 	__be16 protocol;
 	int action;

 	params = rcu_dereference_bh(p->params);

 	tcf_lastuse_update(&p->tcf_tm);
 	tcf_action_update_bstats(&p->common, skb);

 	action = params->action;
 	if (unlikely(action == TC_ACT_SHOT))
 		goto drop;

 	update_flags = params->update_flags;
 	protocol = skb_protocol(skb, false);
 again:
 	switch (protocol) {
 	case cpu_to_be16(ETH_P_IP):
 		if (!tcf_csum_ipv4(skb, update_flags))
 			goto drop;
 		break;
 	case cpu_to_be16(ETH_P_IPV6):
 		if (!tcf_csum_ipv6(skb, update_flags))
 			goto drop;
 		break;
 	case cpu_to_be16(ETH_P_8021AD):
 		fallthrough;
 	case cpu_to_be16(ETH_P_8021Q):
 		if (skb_vlan_tag_present(skb) && !orig_vlan_tag_present) {
 			protocol = skb->protocol;
 			orig_vlan_tag_present = true;
 		} else {
-			struct vlan_hdr *vlan = (struct vlan_hdr *)skb->data;
+			struct vlan_hdr *vlan;

+			if (!pskb_may_pull(skb, VLAN_HLEN))
+				goto drop;
+
+			vlan = (struct vlan_hdr *)skb->data;
 			protocol = vlan->h_vlan_encapsulated_proto;
 			skb_pull(skb, VLAN_HLEN);
 			skb_reset_network_header(skb);
 			vlan_hdr_count++;
 		}
 		goto again;
 	}

 out:
 	/* Restore the skb for the pulled VLAN tags */
 	while (vlan_hdr_count--) {
 		skb_push(skb, VLAN_HLEN);
 		skb_reset_network_header(skb);
 	}

 	return action;

 drop:
 	tcf_action_inc_drop_qstats(&p->common);
 	action = TC_ACT_SHOT;
 	goto out;
 }



